var AdminRecordingsList = &Operation{
	Area: "admin", Group: "recordings", Command: "list",
	Summary:     "List Recordings",
	Description: "<div><Callout type=\"warning\">This API is still supported and behaves the same as before, but will be deprecated in the future. Due to limited support for special characters when filtering recordings by `topic`, it is recommended to use the new [Query Recordings](/docs/api/v1/recordings/query-recordings) API instead.</Callout></div>\n\nLists recordings. You can specify a date range, a parent meeting ID, and the maximum number of recordings to return.\n\nOnly recordings of meetings hosted by or shared with the authenticated user will be listed.\n\nThe list returned is sorted in descending order by the date and time that the recordings were created.\n\nLong result sets are split into [pages](/docs/basics#pagination).\n\n* If `meetingId` is specified, only recordings associated with the specified meeting will be listed. **NOTE**: when `meetingId` is specified, parameter of `siteUrl` will be ignored.\n\n* If `siteUrl` is specified, recordings of the specified site will be listed; otherwise, the API lists recordings of all the user's sites. All available Webex sites and preferred site of the user can be retrieved by [Get Site List](/docs/api/v1/meeting-preferences/get-site-list) API.\n\n#### Request Header\n\n* `timezone`: *[Time zone](https://en.wikipedia.org/wiki/List_of_tz_database_time_zones#List) in conformance with the [IANA time zone database](https://www.iana.org/time-zones). The default is UTC if `timezone` is not defined.*",
	Method:      "GET", Path: "/recordings", Host: HostWebex,
	Params: []Param{
		{Name: "max", In: InQuery, Flag: "max", Usage: "Maximum number of recordings to return in a single page. `max` must be equal to or greater than `1` and equal to or less than `100`."},
		{Name: "from", In: InQuery, Flag: "from", Usage: "Starting date and time (inclusive) for recordings to return, in any [ISO 8601](https://en.wikipedia.org/wiki/ISO_8601) compliant format. `from` cannot be after `to`."},
		{Name: "to", In: InQuery, Flag: "to", Usage: "Ending date and time (exclusive) for List recordings to return, in any [ISO 8601](https://en.wikipedia.org/wiki/ISO_8601) compliant format. `to` cannot be before `from`."},
		{Name: "meetingId", In: InQuery, Flag: "meeting-id", Usage: "Unique identifier for the parent meeting series, scheduled meeting, or meeting instance for which recordings are being requested. If a meeting series ID is specified, the operation returns an array of recordings for the specified meeting series. If a scheduled meeting ID is specified, the operation returns an array of recordings for the specified scheduled meeting. If a meeting instance ID is specified, the operation returns an array of recordings for the specified meeting instance. If no ID is specified, the operation returns an array of recordings for all meetings of the current user. When `meetingId` is specified, the `siteUrl` parameter is ignored."},
		{Name: "hostEmail", In: InQuery, Flag: "host-email", Usage: "Email address for the meeting host. This parameter is only used if the user or application calling the API has the required [admin-level meeting scopes](/docs/meetings#adminorganization-level-authentication-and-scopes). If set, the admin may specify the email of a user in a site they manage and the API will return recordings of that user."},
		{Name: "siteUrl", In: InQuery, Flag: "site-url", Usage: "URL of the Webex site from which the API lists recordings. If not specified, the API lists recordings from all of a user's sites. All available Webex sites and the preferred site of the user can be retrieved by the [Get Site List](/docs/api/v1/meeting-preferences/get-site-list) API."},
		{Name: "integrationTag", In: InQuery, Flag: "integration-tag", Usage: "External key of the parent meeting created by an integration application. This parameter is used by the integration application to query recordings by a key in its own domain, such as a Zendesk ticket ID, a Jira ID, a Salesforce Opportunity ID, etc. An integrationTag created by one client cannot be accessed or used as a filtering parameter by another client. For example, if a meeting has an `integrationTag` of \"Sales\" which is created by the client behind the developer portal, then this integrationTag can't be accessed on the meeting or its recordings by another client. Neither can it be used to filter meetings or recordings by a client other than the one that created the integrationTag of \"Sales\"."},
		{Name: "topic", In: InQuery, Flag: "topic", Usage: "Recording's topic. If specified, the API filters recordings by topic in a case-insensitive manner."},
		{Name: "format", In: InQuery, Flag: "format", Usage: "Recording's file format. If specified, the API filters recordings by format."},
		{Name: "serviceType", In: InQuery, Flag: "service-type", Usage: "The service type for recordings. If this item is specified, the API filters recordings by service-type."},
		{Name: "status", In: InQuery, Flag: "status", Usage: "Recording's status. If not specified or `available`, retrieves recordings that are available. Otherwise, if specified as `deleted`, retrieves recordings that have been moved into the recycle bin. The `purged` status only applies if the user calling the API is a Compliance Officer and `meetingId` is specified."},
		{Name: "timezone", In: InHeader, Flag: "timezone", Usage: "e.g. UTC"},
	},
	Paging:    &Paging{Offset: &OffsetPaging{Start: "", Size: "max", First: 0}},
	TimeRange: TimeISO,
}

var AdminRecordingsListAdminComplianceOfficer = &Operation{
	Area: "admin", Group: "recordings", Command: "list-admin-compliance-officer",
	Summary:     "List Recordings For an Admin or Compliance Officer",
	Description: "<div><Callout type=\"warning\">This API is still supported and behaves the same as before, but will be deprecated in the future. Due to limited support for special characters when filtering recordings by `topic`, it is recommended to use the new [Query Recordings For an Admin or Compliance Officer](/docs/api/v1/recordings/query-recordings-for-an-admin-or-compliance-officer) API instead.</Callout></div>\n\nList recordings for an admin or compliance officer. You can specify a date range, a parent meeting ID, and the maximum number of recordings to return.\n\nThe list returned is sorted in descending order by the date and time that the recordings were created.\n\nLong result sets are split into [pages](/docs/basics#pagination).\n\n* If `meetingId` is specified, only recordings associated with the specified meeting will be listed. Please note that when `meetingId` is specified, parameters of `siteUrl`, `from`, and `to` will be ignored.\n\n* If `siteUrl` is specified, all the recordings on the specified site are listed; otherwise, all the recordings on the admin user's or compliance officer's preferred site are listed. All the available Webex sites and the admin user's or compliance officer's preferred site can be retrieved by the [Get Site List](/docs/api/v1/meeting-preferences/get-site-list) API.\n\n#### Request Header\n\n* `timezone`: *[Time zone](https://en.wikipedia.org/wiki/List_of_tz_database_time_zones#List) in conformance with the [IANA time zone database](https://www.iana.org/time-zones). The default is UTC if `timezone` is not defined.*",
	Method:      "GET", Path: "/admin/recordings", Host: HostWebex,
	Params: []Param{
		{Name: "max", In: InQuery, Flag: "max", Usage: "Maximum number of recordings to return in a single page. `max` must be equal to or greater than `1` and equal to or less than `100`."},
		{Name: "from", In: InQuery, Flag: "from", Usage: "Starting date and time (inclusive) for recordings to return, in any [ISO 8601](https://en.wikipedia.org/wiki/ISO_8601) compliant format. `from` cannot be after `to`. The interval between `from` and `to` must be within 30 days. If `to` is specified, the default value for `from` is `to` minus 7 days. If `to` is also not specified, the default value for `from` is current date and time minus 7 days."},
		{Name: "to", In: InQuery, Flag: "to", Usage: "Ending date and time (exclusive) for List recordings to return, in any [ISO 8601](https://en.wikipedia.org/wiki/ISO_8601) compliant format. `to` cannot be before `from`. The interval between `from` and `to` must be within 30 days. If `from` is specified, the default value for `to` is `from` plus 7 days. If `from` is also not specified, the default value for `to` is the current date and time."},
		{Name: "meetingId", In: InQuery, Flag: "meeting-id", Usage: "Unique identifier for the parent meeting series, scheduled meeting, or meeting instance for which recordings are being requested. If a meeting series ID is specified, the operation returns an array of recordings for the specified meeting series. If a scheduled meeting ID is specified, the operation returns an array of recordings for the specified scheduled meeting. If a meeting instance ID is specified, the operation returns an array of recordings for the specified meeting instance. If not specified, the operation returns an array of recordings for all the current user's meetings. When `meetingId` is specified, the `siteUrl` parameter is ignored."},
		{Name: "siteUrl", In: InQuery, Flag: "site-url", Usage: "URL of the Webex site which the API lists recordings from. If not specified, the API lists recordings from user's preferred site. All available Webex sites and preferred site of the user can be retrieved by [Get Site List](/docs/api/v1/meeting-preferences/get-site-list) API."},
		{Name: "integrationTag", In: InQuery, Flag: "integration-tag", Usage: "External key of the parent meeting created by an integration application. This parameter is used by the integration application to query recordings by a key in its own domain such as a Zendesk ticket ID, a Jira ID, a Salesforce Opportunity ID, etc. An integrationTag created by one client cannot be accessed or used as a filtering parameter by another client. For example, if a meeting has an `integrationTag` of \"Sales\" which is created by the client behind the developer portal, then this integrationTag can't be accessed on the meeting or its recordings by another client. Neither can it be used to filter meetings or recordings by a client other than the one that created the integrationTag of \"Sales\"."},
		{Name: "topic", In: InQuery, Flag: "topic", Usage: "Recording topic. If specified, the API filters recordings by topic in a case-insensitive manner."},
		{Name: "format", In: InQuery, Flag: "format", Usage: "Recording's file format. If specified, the API filters recordings by format."},
		{Name: "serviceType", In: InQuery, Flag: "service-type", Usage: "The service type for recordings. If specified, the API filters recordings by service type."},
		{Name: "status", In: InQuery, Flag: "status", Usage: "Recording's status. If not specified or `available`, retrieves recordings that are available. If specified as `deleted`, retrieves recordings that have been moved to the recycle bin. Otherwise, if specified as `purged`, retrieves recordings that have been purged from the recycle bin."},
		{Name: "timezone", In: InHeader, Flag: "timezone", Usage: "e.g. UTC"},
	},
	Paging:    &Paging{Offset: &OffsetPaging{Start: "", Size: "max", First: 0}},
	TimeRange: TimeISO,
}

