var AdminScim2UsersCreate = &Operation{
	Area: "admin", Group: "scim-2-users", Command: "create",
	Summary:     "Create a user",
	Description: "The SCIM 2 /Users API provides a programmatic way to manage users in Webex Identity using The Internet Engineering Task Force standard SCIM 2.0 standard as specified by [RFC 7643 SCIM 2.0 Core Schema ](https://datatracker.ietf.org/doc/html/rfc7643) and [RFC 7644 SCIM 2.0 Core Protocol](https://datatracker.ietf.org/doc/html/rfc7644).  The WebEx SCIM 2.0  APIs allow clients supporting the SCIM 2.0 standard to manage users, and groups within Webex.  Webex supports the following SCIM 2.0 Schemas:\n\n• urn:ietf:params:scim:schemas:core:2.0:User\n\n• urn:ietf:params:scim:schemas:extension:enterprise:2.0:User\n\n• urn:scim:schemas:extension:cisco:webexidentity:2.0:User\n\n<br/>\n\n**Authorization**\n\nOAuth token rendered by Identity Broker.\n\n<br/>\n\nOne of the following OAuth scopes is required:\n\n- `identity:people_rw`\n\n<br/>\n\nThe following administrators can use this API:\n\n- `id_full_admin`\n\n- `id_user_admin`\n\n<br/>\n\n**Usage**:\n\n1. Input JSON must contain schema: \"urn:ietf:params:scim:schemas:core:2.0:User\".\n\n2. Support 3 schemas :\n    - \"urn:ietf:params:scim:schemas:core:2.0:User\"\n    - \"urn:ietf:params:scim:schemas:extension:enterprise:2.0:User\"\n    - \"urn:scim:schemas:extension:cisco:webexidentity:2.0:User\"\n\n3. Unrecognized schemas (ID/section) are ignored.\n\n4. Read-only attributes provided as input values are ignored.\n\n The following roles cannot be assigned to a user:\n\n1. Location Admin\n\n2. Webex Site Admin",
	Method:      "POST", Path: "/identity/scim/{orgId}/v2/Users", Host: HostWebex,
	Params: []Param{
		{Name: "orgId", In: InPath, Flag: "org-id", Usage: "Webex Identity assigned organization identifier for user's organization."},
	},
	Body: &Body{},
}

var AdminScim2UsersSearch = &Operation{
	Area: "admin", Group: "scim-2-users", Command: "search",
	Summary:     "Search users",
	Description: "<br/>\n\n**Authorization**\n\nOAuth token rendered by Identity Broker.\n\n<br/>\n\nOne of the following OAuth scopes is required:\n\n- `identity:people_rw`\n\n- `identity:people_read`\n\n<br/>\n\nThe following administrators can use this API:\n\n- `id_full_admin`\n\n- `id_user_admin`\n\n- `id_readonly_admin`\n\n- `id_device_admin`\n\n<br/>",
	Method:      "GET", Path: "/identity/scim/{orgId}/v2/Users", Host: HostWebex,
	Params: []Param{
		{Name: "orgId", In: InPath, Flag: "org-id", Usage: "Webex Identity assigned organization identifier for user's organization."},
		{Name: "filter", In: InQuery, Flag: "filter", Usage: "The URL encoded filter. If the value is empty, the API will return all users under the organization.\n\nThe examples below show some search filters:\n\n- `userName` eq \"user1@example.com\"\n\n- `userName` sw \"user1@example\"\n\n- `userName` ew \"example\"\n\n- `phoneNumbers` [ type eq \"mobile\" and value eq \"14170120\"]\n\n- `urn:scim:schemas:extension:cisco:webexidentity:2.0:User:meta.organizationId` eq \"0ae87ade-8c8a-4952-af08-318798958d0c\"\n\n- For more filter patterns, please check [filtering](https://datatracker.ietf.org/doc/html/rfc7644#section-3.4.2.2).\n\n| **Attributes** | **Operators** |\n|-----|-----|\n| **SCIM Core** &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; | ---- |\n| `id` | eq |\n| `userName` | eq sw ew |\n| `name.familyName` | eq sw ew |\n| `name.givenName` | eq sw |\n| `name.middleName` | eq sw |\n| `name.formatted` | eq sw |\n| `displayName` | eq sw ew |\n| `nickName` | eq sw ew |\n| `emails.display` | eq sw ew |\n| `emails.value` | eq sw ew |\n| `phoneNumbers.value` | eq sw ew |\n| `phoneNumbers.display` | eq sw ew |\n| **Enterprise Extensions** | ---- |\n| `employeeNumber` | eq sw ew |\n| `costCenter` | eq sw ew |\n| `organization` | eq sw ew |\n| `division` | eq sw ew |\n| `department` | eq sw ew |\n| `manager.value` | eq |\n| `manager.displayName` | eq sw ew |"},
		{Name: "attributes", In: InQuery, Flag: "attributes", Usage: "A multi-valued list of string names for resource attributes to return in the response, like 'userName,department,emails'. It supports the SCIM id 'urn:ietf:params:scim:schemas:extension:enterprise:2.0:User,userName'. The default is empty, all attributes will be returned"},
		{Name: "excludedAttributes", In: InQuery, Flag: "excluded-attributes", Usage: "A multi-valued list of strings names for resource attributes to be removed from the default set of attributes to return. The default is empty, all attributes will be returned"},
		{Name: "sortBy", In: InQuery, Flag: "sort-by", Usage: "A string for the attribute whose value can be used to order the returned responses. Now we only allow `userName`, `id`, `meta.lastModified` to sort."},
		{Name: "sortOrder", In: InQuery, Flag: "sort-order", Usage: "A string for the order in which the 'sortBy' parameter is applied. Allowed values are 'ascending' and 'descending'."},
		{Name: "startIndex", In: InQuery, Flag: "start-index", Usage: "An integer for the 1-based index of the first query result. The default is 1."},
		{Name: "count", In: InQuery, Flag: "count", Usage: "An integer for the maximum number of query results per page.  The default is 100."},
		{Name: "returnGroups", In: InQuery, Flag: "return-groups", Usage: "Define whether the group information needs to be returned.  The default is false."},
		{Name: "includeGroupDetails", In: InQuery, Flag: "include-group-details", Usage: "Define whether the group information with details needs to be returned. The default is false."},
		{Name: "groupUsageTypes", In: InQuery, Flag: "group-usage-types", Usage: "Returns groups with details of the specified group type."},
	},
	Paging: &Paging{Offset: &OffsetPaging{Start: "startIndex", Size: "count", First: 1}},
}

